/// The store's key list written as an OpenSSH allowed_signers file for one
/// `ssh-keygen` call, in a private file removed when dropped.
pub(crate) struct AllowedFile(pub Utf8PathBuf);

impl AllowedFile {
    fn write(text: &str) -> Result<Self, String> {
        static N: std::sync::atomic::AtomicU64 = std::sync::atomic::AtomicU64::new(0);
        let dir = Utf8PathBuf::from_path_buf(std::env::temp_dir())
            .map_err(|p| format!("the temporary directory {} is not UTF-8", p.display()))?;
        let path = dir.join(format!(
            "war-store-signers-{}-{}",
            std::process::id(),
            N.fetch_add(1, std::sync::atomic::Ordering::Relaxed)
        ));
        let mut options = std::fs::OpenOptions::new();
        options.write(true).create_new(true);
        #[cfg(unix)]
        {
            use std::os::unix::fs::OpenOptionsExt;
            options.mode(0o600);
        }

fn read_store(store: &str, test: bool) -> Result<StoreBinding, (&'static str, String)> {
    let current = crate::authority_cmd::store::read_current(std::path::Path::new(store), test)
        .map_err(|e| {
            (
                "authority.verify-unavailable",
                format!(
                    "the protected store {store} configured in openwarrant.toml could not be \
                     read ({e}). Nothing falls back to docs/authority/roles.toml (OW-WAR-0138): \
                     an unreadable store authorizes nobody"
                ),
            )
        })?;
    Ok(StoreBinding {
        store: store.to_owned(),
        head: current.head,
        test_mode: current.test_mode,
        revision: current.revision,
    })
}

/// This repository's binding, read now.
pub(crate) fn binding(repo: &Repository) -> Binding {
    let Some(a) = &repo.config.authority else {
        return Binding::Register;
    };
    match read_store(&a.store, a.unprotected_test_store) {
        Ok(s) => Binding::Store(s),
        Err((rule, why)) => Binding::Failed { rule, why },
    }
}

/// Who `war sign` signs as, and against which key list (OW-WAR-0138).
pub(crate) struct Signer {
    pub principal: String,
    /// The allowed_signers file the signature is made and checked against.
    pub allowed: Utf8PathBuf,
    /// Held so the store's temporary key list lives as long as the signing.
    _store_file: Option<AllowedFile>,
    /// The store head the grant was read at; `None` on the register path.
    pub head: Option<String>,
    pub via: String,
}

/// Resolve `actor` for signing `acts`, or the refusal with its rule.
///
/// Without a store: `roles.toml`'s `ssh_principal` and `allowed_signers`, as
/// before. With one: the store's binding, kind and roles, and a refusal
/// `authority.legacy-fallback` when only the working-tree register knows the
/// actor. Nothing is signed before this answers.
pub(crate) fn signer_for(
    repo: &Repository,
    actor: &str,
    acts: &[Act],
) -> Result<Signer, (&'static str, String)> {
    match binding(repo) {
        Binding::Register => {
            let principal = crate::sign::principal_of(repo, actor)
                .map_err(|why| ("sign.ssh-principal", why))?;
            Ok(Signer {
                principal,
                allowed: repo.root.join("docs/authority/allowed_signers"),
                _store_file: None,
                head: None,
                via: String::new(),
            })
        }
        Binding::Failed { rule, why } => Err((rule, format!("{why}; nothing was signed"))),
        Binding::Store(store) => match store.signer(actor, acts) {
            Ok((principal, file)) => Ok(Signer {
                principal,
                allowed: file.0.clone(),
                _store_file: Some(file),
                head: Some(store.head.clone()),
                via: store.describe(),
            }),
            Err(v) => {
                let legacy = crate::sign::principal_of(repo, actor).ok();
                match (v, legacy) {
                    (Verdict::NotHuman { why }, Some(principal)) => Err((
                        "authority.legacy-fallback",
                        format!(
                            "docs/authority/roles.toml binds {actor} to principal {principal:?}, \
                             and {why}. With a store configured the working-tree register grants \
                             nothing (OW-WAR-0138); nothing was signed"
                        ),
                    )),
                    (v, _) => Err((v.rule(), format!("{}; nothing was signed", v.why()))),
                }
            }
        },
    }
}

/// The store's head now, for the check after the key was asked: a grant read
/// at one head is not a grant at another (`allows --expected-head`).
pub(crate) fn store_head(repo: &Repository) -> Result<Option<String>, String> {
    match binding(repo) {
        Binding::Register => Ok(None),
        Binding::Store(s) => Ok(Some(s.head)),
        Binding::Failed { why, .. } => Err(why),
    }
}

/// Apply the configured store's policy to a configuration just read
/// (OW-WAR-0138 D-006), when the repository is opened. No `[authority]`
/// table: nothing changes.
pub(crate) fn govern(config: &mut openwarrant_core::config::RepositoryConfig) {
    let Some(a) = config.authority.clone() else {
        return;
    };
    match read_store(&a.store, a.unprotected_test_store) {
        Ok(s) => match (&s.revision.policy, s.revision.version()) {
            (Some(policy), 2) => config.govern_from_store(&a.store, &s.head, s.test_mode, policy),
            _ => config.govern_fail_closed(
                &a.store,
                "authority.store-v1",
                format!(
                    "{}: its head is a v1 revision, which carries no actor kind and no policy. \
                     Until a v1-to-v2 transition is activated the store authorizes nobody, and the \
                     protected policy keys take their most restrictive values, not \
                     openwarrant.toml's",
                    s.describe()
                ),
            ),
        },
        Err((rule, why)) => config.govern_fail_closed(&a.store, rule, why),
    }
}

/// What `war check` says once about where authority and policy come from.
pub(crate) fn protection_report(repo: &Repository) -> Vec<crate::diagnostic::Diagnostic> {
    use crate::diagnostic::Diagnostic;
    use openwarrant_core::config::Governance;
    let config = repo.relative(&repo.root.join("openwarrant.toml"));
    match &repo.config.governance {
        Governance::Unprotected => vec![Diagnostic::warn(
            "authority.unprotected",
            config,
            "no protected authority store is configured (`[authority] store`). \
             docs/authority/roles.toml, docs/authority/allowed_signers and the policy keys that \
             decide whether work may close ([independence], allow_automated_resolution, \
             require_user_presence, verifier_argv) are working-tree files the performer can \
             write; review of them is the control (THREAT_MODEL row 6, docs/AUTHENTICATION.md)",
        )],
        Governance::FailedClosed { rule, why, .. } => {
            vec![Diagnostic::error(*rule, config, why.clone())]
        }
        Governance::Store {
            store,
            head,
            test_mode,
            divergences,
        } => {
            let mut out = vec![Diagnostic::pass(
                "authority.store",
                format!(
                    "the store {store} at {head} governs the actor binding and the protected \
                     policy keys; roles.toml and allowed_signers grant nothing"
                ),
            )];
            if *test_mode {
                out.push(Diagnostic::warn(
                    "authority.test-store",
                    config.clone(),
                    format!(
                        "{store} is an UNPROTECTED TEST STORE (`unprotected_test_store = true`): \
                         the account running war owns it, so it separates nothing from the \
                         performer. Every signed verdict read through it says so"
                    ),
                ));
            }
            for d in divergences {
                out.push(Diagnostic::error(
                    "policy.unprotected-divergence",
                    config.clone(),
                    format!(
                        "{} is {} in openwarrant.toml and {} in the store {store} at {head}. \
                         The store's value governs; edit the store through a signed transition, \

// SPDX-License-Identifier: Apache-2.0
//! `war sign` — the human's half of every seam, as one command at a terminal.
//!
//! # Why this exists
//!
//! Every authority act in this repository is a two-half seam: an agent emits a
//! request, a human ingests a signed response. That shape is right (§27.2) and
//! it was, in practice, three steps: emit the request to a file, hand-write a
//! response with six fields and one `[[judgment]]` block per residual risk,
//! then ingest it. Nobody hand-writes fifty-seven of those. What happened
//! instead is that an agent drafted every response and the human said "sign
//! it" — which is a signature in name only, and the friction of the three
//! steps was the only thing stopping the agent from running the third too.
//!
//! `war sign` collapses the human's part to one screen and one keystroke,
//! and replaces friction with a control that is actually a control:
//!
//! - **It refuses without a terminal.** An agent's shell has no TTY, so the
//!   command cannot be run from inside one. This is a speed bump against an
//!   agent completing the loop by accident or by "helpfulness", not a
//!   cryptographic guarantee; a pseudo-terminal defeats it.
//! - **`--ssh-sign` is the stronger form, and the one that works from inside
//!   an agent session.** Measured: Claude Code's `!` prefix runs in the agent's
//!   own shell and has no TTY, so the terminal path refuses it — correctly, and
//!   uselessly for a human sitting in that session. `--ssh-sign` signs the
//!   response file's bytes with `ssh-keygen -Y sign` under namespace
//!   `oh.war/response`, verifies at once against a human-written
//!   `docs/authority/allowed_signers`, and refuses if it does not verify. No
//!   prompt, no TTY: the human act is the ssh agent's confirmation dialog,
//!   which exists only if the key was loaded with `ssh-add -c`. Without `-c`
//!   the AI agent's shell can reach the same socket and sign as the human, and
//!   `war` cannot tell the two apart. That is the one thing the operator must
//!   get right, and the docs say so where the key is configured. A security
//!   key (`sk-`) is the exception (OW-WAR-0138): its signature carries the
//!   authenticator's presence flag, `war` reads it after verification and
//!   records it, and `[policy] require_user_presence` refuses any signature
//!   that does not show it. `docs/AUTHENTICATION.md` is the contract.
//! - **It shows what is being signed, not the TOML.** Title, revision, what
//!   changed (for an amendment), obligations, every residual risk with its
//!   consequence, the digest. Those are the things the signer is accepting.
//!   Everything else in a response is boilerplate.
//! - **The drafted wording is a template, and says so.** `authorize.rs` is
//!   right that pre-filling the meaning would make the signer a signatory to
//!   text an agent wrote. This is the other case: text a deterministic tool
//!   rendered from the record's own facts, shown to the signer on a terminal
//!   before they confirm, and recorded as `signed_via = "tty"`. That is more
//!   honest than the paragraph-per-response practice it replaces.
//! - **It reuses every existing refusal.** On `y` it writes the response to
//!   `docs/authority/responses/` and calls the same ingest that a hand-written
//!   response goes through. Agent-by-kind, stale digest, self-authorization,
//!   missing amendment, unsupported outcome: nothing here bypasses them.
//!
//! There is deliberately no `--yes`. A flag that skipped the prompt would be
//! the first thing an agent reached for.

/// journal so a later reader can tell a terminal confirmation from a
/// hand-written file — or, later, from an ssh signature.
pub const CHANNEL_TTY: &str = "tty";
/// Signed with `ssh-keygen -Y sign`; the `.sig` sidecar beside the response
/// verifies against `docs/authority/allowed_signers`.
pub const CHANNEL_SSH: &str = "ssh";
/// The `-n` namespace every signature is made and verified under. A signature
/// made for another purpose with the same key does not verify here.
pub const SSH_NAMESPACE: &str = "oh.war/response";

/// One act awaiting a human.
#[derive(Debug)]
pub enum Pending {
    Authorize {
        alias: String,
        request: AuthorizationRequest,
        /// Present when this would be revision N+1 under an amendment.
        amendment: Option<AmendmentSummary>,
        revision: u32,
    },
    Resolve {
        alias: String,
        request: ResolutionRequest,
        profile: String,
        /// Present when a resolution is already recorded for this contract and

    /// `docs/authority/responses/`. For an agent to troubleshoot an act before
    /// asking a human to sign it.
    pub dry_run: bool,
    /// Sign the response file with the actor's ssh key via `ssh-keygen -Y
    /// sign`, verified at once against `docs/authority/allowed_signers`. No
    /// terminal needed: the human act is the agent's confirmation dialog
    /// (`ssh-add -c`), which no shell can answer.
    pub ssh_sign: bool,
    /// Verify an existing response's `.sig` sidecar and stop. Writes nothing.
    pub verify: bool,
    /// For a correction: what kind of change it admits (OW-WAR-0064).
    pub kind: Option<openwarrant_core::correction::CorrectionKind>,
    /// OW-ADR-0029: the acts offered are revocations of signed classes, not
    /// the pending queue. A sweep never revokes.
    pub revoke: bool,
}

